// PythonSDKOpts contains options for Query.PythonSDK
type PythonSDKOpts struct {
	//
	// Starter under templates/<template> for a module generated without source.
	//
	Template string // python-sdk (../../:0:0)
	//
	// Python version written to a new module's pyproject.toml; empty keeps the template's.
	//
	PythonVersion string // python-sdk (../../:0:0)
	//
	// Whether a new module builds with uv instead of pip.
	//
	UseUv bool // python-sdk (../../:0:0)
	//
	// Base container image written to a new module's pyproject.toml; empty keeps the SDK default.
	//
	BaseImage string // python-sdk (../../:0:0)
	//
	// Run a module on the module runtime this SDK publishes instead of an
	// entrypoint: the runtime builds the module and answers every call, as the
	// runtime built into the engine did. A module whose files are not its
	// directory alone takes this path whether the flag is set or not. A module
	// that names a runtime of its own keeps it.
	//
	LegacyRuntime bool // python-sdk (../../:0:0)
	//
	// The engine release to generate for, from v1.0.0-beta.26 to the release
	// this SDK targets; empty generates for the targeted release.
	//
	TargetVersion string // python-sdk (../../:0:0)
}

// Manage Dagger modules that use the Python SDK.
func (r *Query) PythonSDK(opts ...PythonSDKOpts) *PythonSDK { // python-sdk (../../:0:0)
	q := r.query.Select("pythonSdk")
	for i := len(opts) - 1; i >= 0; i-- {
		// `template` optional argument
		if !querybuilder.IsZeroValue(opts[i].Template) {
			q = q.Arg("template", opts[i].Template)
		}
		// `pythonVersion` optional argument
		if !querybuilder.IsZeroValue(opts[i].PythonVersion) {
			q = q.Arg("pythonVersion", opts[i].PythonVersion)
		}
		// `useUv` optional argument
		if !querybuilder.IsZeroValue(opts[i].UseUv) {
			q = q.Arg("useUv", opts[i].UseUv)
		}
		// `baseImage` optional argument
		if !querybuilder.IsZeroValue(opts[i].BaseImage) {
			q = q.Arg("baseImage", opts[i].BaseImage)
		}
		// `legacyRuntime` optional argument
		if !querybuilder.IsZeroValue(opts[i].LegacyRuntime) {
			q = q.Arg("legacyRuntime", opts[i].LegacyRuntime)
		}
		// `targetVersion` optional argument
		if !querybuilder.IsZeroValue(opts[i].TargetVersion) {
			q = q.Arg("targetVersion", opts[i].TargetVersion)
		}
	}

	return &PythonSDK{
		query:     q,
		refetchID: r.refetchID,
	}
}

// New calls PythonSDK on the default connection.
// Use Connect(connection).PythonSDK to call it on an explicit connection.
//
// Manage Dagger modules that use the Python SDK.
func New(opts ...PythonSDKOpts) *PythonSDK {
	return Connect().PythonSDK(opts...)
}
